import { Item } from '@gaudi/design-system/core/Item';
import { IconTile } from '@gaudi/design-system/core/Icon';
import { Badge } from '@gaudi/design-system/core/Pill';
import {
  DialogConfirmationHeader,
  DialogConfirmationRoot as DialogConfirmation,
  DialogConfirmationAction,
  DialogConfirmationCancel,
  DialogConfirmationContent,
  DialogConfirmationDescription,
  DialogConfirmationFooter,
  DialogConfirmationMedia,
  DialogConfirmationTitle,
  DialogConfirmationTrigger
} from '@gaudi/design-system/core/Dialog';
import { default as Button } from '@gaudi/design-system/core/Button';
import { RegistryIcon } from '@gaudi/design-system/icons/RegistryIcon';
const SECURITY_ITEMS = [
  {
    icon: (
      <RegistryIcon
        lucide='LockIcon'
        className='text-text-muted size-4'
      />
    ),
    title: 'Password Policy',
    description: 'Confirm the password is unique',
    status: 'Pending'
  },
  {
    icon: (
      <RegistryIcon
        lucide='FingerprintPatternIcon'
        className='text-text-muted size-4'
      />
    ),
    title: 'Biometric Status',
    description: 'Turn on disk encryption',
    status: 'Done'
  },
  {
    icon: (
      <RegistryIcon
        lucide='KeySquareIcon'
        className='text-text-muted size-4'
      />
    ),
    title: 'Active Sessions',
    description: 'Sign out devices you do not recognise',
    status: 'Pending'
  }
];
export function Pattern() {
  return (
    <DialogConfirmation>
      <DialogConfirmationTrigger asChild>
        <Button variant='outline'>Account health check</Button>
      </DialogConfirmationTrigger>
      <DialogConfirmationContent className='gap-0 overflow-hidden p-0 sm:max-w-sm'>
        {/* Header */}
        <DialogConfirmationHeader className='flex flex-col items-center justify-center gap-1.5 px-4 pt-6 pb-5 text-center'>
          <DialogConfirmationMedia className='size-12 rounded-full bg-success-muted text-success'>
            <RegistryIcon lucide='ShieldAlertIcon' className='size-6' />
          </DialogConfirmationMedia>
          <DialogConfirmationTitle className='text-base font-semibold'>
            Advanced Security Audit
          </DialogConfirmationTitle>
          <DialogConfirmationDescription className='p-0 text-sm'>
            Summary of your account status and security settings.
          </DialogConfirmationDescription>
        </DialogConfirmationHeader>

        {/* Content */}
        <div className='grid gap-2 px-4'>
          {SECURITY_ITEMS.map((item) => (
            <Item variant='outline' size='sm'
              key={item.title}
              className='flex items-center justify-between rounded-md border-dashed px-3 py-2'
            >
              <div className='flex items-center gap-2.5'>
                <IconTile aria-hidden='true' size='xs'>
                  {item.icon}
                </IconTile>
                <div className='flex flex-col gap-0.5'>
                  <span className='text-sm font-medium'>{item.title}</span>
                  <span className='text-text-muted text-xs'>
                    {item.description}
                  </span>
                </div>
              </div>
              <Badge
                variant={
                  item.status === 'Pending' ? 'warning-light' : 'success-light'
                }
              >
                {item.status}
              </Badge>
            </Item>
          ))}
        </div>

        {/* Footer */}
        {/* The content is `p-0`, so there is no padding to escape: the footer's
       built-in `-mx-3 -mb-3` pushed the bar OUTSIDE the dialog, where
       `overflow-hidden` clipped it - which is why it looked like it had no
       padding. Cancelling the breakout puts it flush edge-to-edge with its
       own `p-4` intact. */}
        <DialogConfirmationFooter className='mx-0 mb-0 grid grid-cols-1 gap-2 p-4'>
          <DialogConfirmationAction variant='default' className='flex-1'>
            Start Deep Audit
          </DialogConfirmationAction>
          <DialogConfirmationCancel variant='ghost' className='flex-1'>
            Skip for now
          </DialogConfirmationCancel>
        </DialogConfirmationFooter>
      </DialogConfirmationContent>
    </DialogConfirmation>
  );
}
